create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, username text unique not null, display_name text, avatar_url text, created_at timestamptz default now());
create table if not exists public.conversations (id uuid primary key default gen_random_uuid(), type text not null default 'direct', created_at timestamptz default now());
create table if not exists public.conversation_members (conversation_id uuid references public.conversations(id) on delete cascade, user_id uuid references auth.users(id) on delete cascade, joined_at timestamptz default now(), primary key(conversation_id,user_id));
create table if not exists public.messages (id bigint generated by default as identity primary key, conversation_id uuid not null references public.conversations(id) on delete cascade, sender_id uuid references auth.users(id) on delete cascade not null, body text, attachment_url text, attachment_name text, created_at timestamptz default now());
create index if not exists messages_conversation_created on public.messages(conversation_id,created_at);
alter table public.profiles enable row level security;
alter table public.conversations enable row level security;
alter table public.conversation_members enable row level security;
alter table public.messages enable row level security;
drop policy if exists "profiles readable" on public.profiles;
drop policy if exists "own profile insert" on public.profiles;
drop policy if exists "messages readable" on public.messages;
drop policy if exists "messages insert own" on public.messages;
drop policy if exists "conversations readable" on public.conversations;
drop policy if exists "members readable" on public.conversation_members;
drop policy if exists "messages member readable" on public.messages;
drop policy if exists "messages member insert" on public.messages;
create policy "profiles readable" on public.profiles for select to authenticated using (true);
create policy "own profile insert" on public.profiles for insert to authenticated with check (auth.uid()=id);
create policy "conversations readable" on public.conversations for select to authenticated using (exists(select 1 from public.conversation_members m where m.conversation_id=id and m.user_id=auth.uid()));
create policy "members readable" on public.conversation_members for select to authenticated using (user_id=auth.uid() or exists(select 1 from public.conversation_members m where m.conversation_id=conversation_id and m.user_id=auth.uid()));
create policy "messages member readable" on public.messages for select to authenticated using (exists(select 1 from public.conversation_members m where m.conversation_id=messages.conversation_id and m.user_id=auth.uid()));
create policy "messages member insert" on public.messages for insert to authenticated with check (auth.uid()=sender_id and exists(select 1 from public.conversation_members m where m.conversation_id=messages.conversation_id and m.user_id=auth.uid()));

insert into public.conversations(id,type) values('00000000-0000-4000-8000-000000000003','direct') on conflict (id) do nothing;
insert into storage.buckets (id,name,public) values ('documents','documents',true) on conflict (id) do update set public=true;
drop policy if exists "documents read" on storage.objects;
drop policy if exists "documents upload own folder" on storage.objects;
create policy "documents read" on storage.objects for select to authenticated using (bucket_id='documents');
create policy "documents upload own folder" on storage.objects for insert to authenticated with check (bucket_id='documents' and (storage.foldername(name))[1]=auth.uid()::text);
